"""Offline contract checks and handler tests; these do not render a browser."""
import json
from pathlib import Path
import subprocess
import unittest
from html.parser import HTMLParser


ROOT = Path(__file__).resolve().parent


class Page(HTMLParser):
    def __init__(self):
        super().__init__()
        self.nodes = []
        self.stack = []
        self.feed((ROOT / 'index.html').read_text())

    def handle_starttag(self, tag, attrs):
        node = dict(tag=tag, attrs=dict(attrs), text='', parents=self.stack.copy())
        self.nodes.append(node)
        if tag not in {'meta', 'input', 'br', 'link', 'hr'}:
            self.stack.append(node)

    def handle_endtag(self, tag):
        if self.stack and self.stack[-1]['tag'] == tag:
            self.stack.pop()

    def handle_data(self, data):
        for node in self.stack:
            node['text'] += data


class TrainingPageTests(unittest.TestCase):
    def setUp(self):
        self.page = Page()
        self.ids = {n['attrs']['id']: n for n in self.page.nodes if 'id' in n['attrs']}

    def test_content_and_initial_visibility(self):
        self.assertEqual(len(self.ids), sum('id' in n['attrs'] for n in self.page.nodes))
        for name in ('workspace', 'notes', 'tasks', 'chat', 'question', 'ask',
                     'answer', 'hint', 'transport', 'effects', 'consent', 'start',
                     'reset', 'status'):
            self.assertIn(name, self.ids)
        self.assertEqual(self.ids['workspace']['attrs']['data-phase'], 'ready')
        self.assertNotIn('hidden', self.ids['workspace']['attrs'])
        self.assertIn('hidden', self.ids['hint']['attrs'])
        self.assertIn('disabled', self.ids['show-hint']['attrs'])
        self.assertEqual(self.ids['transport']['tag'], 'details')
        self.assertNotIn('open', self.ids['transport']['attrs'])
        self.assertIn(self.ids['transport'], self.ids['diagnostics']['parents'])
        self.assertLess(self.page.nodes.index(self.ids['workspace']),
                        self.page.nodes.index(self.ids['transport']))
        self.assertEqual(self.ids['notes']['text'], 'Observe the queue before changing it.')
        tasks = [n['text'] for n in self.page.nodes
                 if n['tag'] == 'li' and self.ids['tasks'] in n['parents']]
        self.assertEqual(tasks, ['Inspect the training queue.', 'Record what changed.'])
        scripts = [n for n in self.page.nodes if n['tag'] == 'script']
        self.assertEqual(scripts[0]['attrs'].get('src'), 'reply-client.js')
        self.assertIn('Exercise requests may fail.', self.ids['effects']['text'])
        self.assertIn('Reset returns the training state to ready.', self.ids['effects']['text'])

    def test_exercise_and_assistant_handlers(self):
        nodes = {key: {k: value[k] for k in ('attrs', 'text')}
                 for key, value in self.ids.items()}
        inline = '\n'.join(n['text'] for n in self.page.nodes
                           if n['tag'] == 'script' and 'src' not in n['attrs'])
        payload = dict(nodes=nodes, script=inline, client=(ROOT / 'reply-client.js').read_text())
        result = subprocess.run(['node', '-e', HANDLER_CHECKS], input=json.dumps(payload),
                                capture_output=True, text=True, cwd=ROOT)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)


HANDLER_CHECKS = r"""
const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const source = JSON.parse(fs.readFileSync(0, 'utf8'));
const nodes = {};
for (const [id, node] of Object.entries(source.nodes)) {
  const attrs = {...node.attrs};
  nodes[id] = {
    attrs, textContent: node.text, value: attrs.value ?? node.text,
    dataset: {phase: attrs['data-phase']}, hidden: 'hidden' in attrs,
    disabled: 'disabled' in attrs, checked: 'checked' in attrs,
    setAttribute(name, value) { this.attrs[name] = value; },
    focus() { this.focused = true; }
  };
}
const context = vm.createContext({document: {getElementById: id => nodes[id]}});
context.window = context;
vm.runInContext(source.client, context);
vm.runInContext(source.script, context);
const click = id => nodes[id].onclick();
const submit = () => nodes.chat.onsubmit({preventDefault() {}});
const phase = () => nodes.workspace.dataset.phase;
const snapshot = () => [nodes.notes.value, nodes.tasks.textContent,
                        nodes.question.value, nodes.answer.textContent];
(async () => {
  assert.equal(phase(), 'ready');
  nodes.notes.value = 'Learner notes';
  nodes.tasks.textContent += '\nLearner task';
  nodes.question.value = 'A learner question?';
  nodes.answer.textContent = 'Previous answer';
  const saved = snapshot();
  click('start');
  assert.equal(phase(), 'ready');
  assert.equal(nodes.consent.focused, true);
  click('show-hint');
  assert.equal(nodes.hint.hidden, true);
  nodes.consent.checked = true;
  click('start');
  assert.equal(phase(), 'running');
  assert.equal(nodes.hint.hidden, true);
  assert.equal(nodes['show-hint'].disabled, false);
  assert.deepEqual(snapshot(), saved);
  click('show-hint');
  assert.equal(nodes.hint.hidden, false);
  assert.equal(nodes['show-hint'].attrs['aria-expanded'], 'true');
  await submit();
  assert.deepEqual(Array.from(context.ReplyClient.requests), ['A learner question?']);
  assert.equal(nodes.answer.textContent,
    'Your notes and tasks stay in the workspace. Start the exercise to investigate the queue.');
  assert.match(nodes.diagnostics.textContent, /fixture-json/);
  assert.equal(nodes.transport.attrs.open, undefined);
  assert.deepEqual(snapshot().slice(0, 3), saved.slice(0, 3));
  const answered = snapshot();
  click('reset');
  assert.equal(phase(), 'ready');
  assert.equal(nodes.workspace.hidden, false);
  assert.equal(nodes.hint.hidden, true);
  assert.equal(nodes['show-hint'].disabled, true);
  assert.equal(nodes['show-hint'].attrs['aria-expanded'], 'false');
  assert.equal(nodes.consent.checked, false);
  assert.deepEqual(snapshot(), answered);
  click('start');
  assert.equal(phase(), 'ready');
  await submit();
  assert.equal(phase(), 'ready');
  assert.deepEqual(snapshot(), answered);
  // An alternate provider result proves that answers are not hard-coded.
  context.ReplyClient = {ask: async question => {
    assert.equal(question, nodes.question.value);
    return {answer: '<b>Different provider answer</b>', diagnostics: {debug: 'private'}};
  }};
  await submit();
  assert.equal(nodes.answer.textContent, '<b>Different provider answer</b>');
  context.ReplyClient = {ask: async () => {throw new Error('unavailable');}};
  const beforeFailure = snapshot();
  await submit();
  assert.deepEqual(snapshot(), beforeFailure);
  assert.match(nodes['chat-status'].textContent, /Try Ask again/);
  assert.equal(nodes.ask.disabled, false);
  let resolve;
  let calls = 0;
  context.ReplyClient = {ask: () => {
    calls++;
    return new Promise(done => {resolve = done;});
  }};
  const pending = submit();
  assert.equal(nodes.ask.disabled, true);
  await submit();
  assert.equal(calls, 1);
  click('reset');
  assert.deepEqual(snapshot(), beforeFailure);
  resolve({answer: 'Recovered answer', diagnostics: {}});
  await pending;
  assert.equal(nodes.answer.textContent, 'Recovered answer');
  assert.equal(nodes.ask.disabled, false);
  assert.equal(phase(), 'ready');
  console.log('Consent, hint, preservation, provider, failure and pending checks passed.');
})().catch(error => { console.error(error); process.exitCode = 1; });
"""


if __name__ == '__main__':
    unittest.main(verbosity=2)

